"""Catalogue data for manga.akiba.tokyo.jp.

Two sources:
  * catalog.json (in the image, from git): the approved style tree. It is generated by
    tools/manga_catalog/export_site_tree.py and must not be edited by hand.
  * the data directory (a named Docker volume at /data): state.json (edits, publish flags,
    versions, samples, regeneration requests, API access) and files/<node id>/*.jpg.

An empty data directory boots: every node starts published, and the seed samples are imported.

Prompt composition (approved 2026-09-27):
  * API prompt: level 1 = common + level-1 words; level 2 and below = common + the words from level 2
    down. The level-1 words are not added under level 2: a level-2 style is complete on its own, and
    the level-1 words pull the picture back to the level-1 face.
    At level 3 the level-3 words follow l3_lead ("where it differs from the above, follow this"): a
    level-3 style fixes line, tone, eyes, proportions, background and mood, and overrides the level-2
    words where they disagree (the samples were made with the same lead).
  * Sample prompt: level 1 (and 3) = style prompt + subject + person + place + avoid (one picture).
    Level 2 = two pictures: step 1 = common + level-1 words + that genre's scene + avoid; step 2 = the
    step-1 picture redrawn with l2_edit (the level-2 words). The recorded prompt joins both steps.
    Level 3 = two pictures too, from a scene of its own level-2 branch (not the level-2 sample): step 1 =
    common + level-2 words + l3_scenes[level 2] + avoid; step 2 = redrawn with l2_edit, where the look is
    the level-2 words, l3_lead and the level-3 words.

A prompt never changes without its picture (the owner's absolute rule, 2026-09-27): an edit that changes
a branch's API prompt or sample prompt queues that branch's picture for regeneration.
"""
from __future__ import annotations

import copy
import hashlib
import hmac
import io
import json
import os
import re
import secrets
import threading
from datetime import datetime, timezone
from pathlib import Path

from PIL import Image, ImageOps

APP_DIR = Path(__file__).resolve().parent
CATALOG_FILE = APP_DIR / "catalog.json"
SEED_DIR = APP_DIR / "seed"
# Comparison pictures: the same sample prompt drawn by another image model (records in git, pictures staged
# by tools/manga_catalog/prepare_compare.py into compare/files/, outside the volume). Not part of the style.
COMPARE_DIR = APP_DIR.parent / "compare"
COMPARE_NAME = re.compile(r"^compare-([a-z0-9-]+)-([0-9a-f]{12})\.jpg$")

SUBJECT = "upper_body"
SAMPLE_SIZE = (768, 1024)      # 3:4, long edge 1024 (approved size)
THUMB_SIZE = (384, 512)        # 3:4, long edge 512 (approved size)
MAX_UPLOAD_BYTES = 20 * 1024 * 1024
MAX_PIXELS = 16_000_000
MODEL_ID = "chatgpt-image"
DEFAULT_MODEL_VERSION = "gpt-image-2.5-sunburst"
LANGS = ("ja", "en")
FIELDS = ("title", "summary", "words")
EDITABLE = {
    "title_ja": ("title", "ja", 80), "title_en": ("title", "en", 120),
    "summary_ja": ("summary", "ja", 200), "summary_en": ("summary", "en", 300),
    "words_ja": ("words", "ja", 1200), "words_en": ("words", "en", 2000), "words_tags": ("words", "tags", 600),
}
PROMPT_LIMIT = 8000
TITLE_BRACKETS = "「」『』《》"
ISO_Z = re.compile(r"^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ$")
STALE_NOTE = "言葉が変わったので、今の言葉で絵を作り直す"


class InputError(ValueError):
    """A problem with admin input; the message is shown to the admin (Japanese)."""


def now_iso() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _digest(obj) -> str:
    return hashlib.sha256(json.dumps(obj, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()


def _jpeg(im: Image.Image, quality: int) -> bytes:
    buf = io.BytesIO()
    im.save(buf, "JPEG", quality=quality, optimize=True, progressive=True)
    return buf.getvalue()


def _write_atomic(path: Path, data: bytes) -> None:
    tmp = path.with_name(f".{path.name}.{secrets.token_hex(4)}.tmp")
    with open(tmp, "wb") as fh:
        fh.write(data)
        fh.flush()
        os.fsync(fh.fileno())
    os.replace(tmp, path)


def process_image(raw: bytes, *, color: bool = False, preserve_aspect: bool = False) -> tuple[bytes, bytes]:
    """PNG/JPEG -> sample 768x1024 and thumbnail 384x512; L by default, RGB with color=True.

    The picture is cropped to 3:4 around the upper middle (the samples are upper-body shots).
    A JPEG already in the target mode and 768x1024 without metadata is kept byte for byte.
    """
    if not raw:
        raise InputError("画像が空です。")
    if len(raw) > MAX_UPLOAD_BYTES:
        raise InputError("画像が 20MB を超えています。")
    try:
        im = Image.open(io.BytesIO(raw))
        fmt, (w, h) = im.format, im.size
    except Exception as exc:  # noqa: BLE001 - any decoder error is bad input
        raise InputError("画像として読めません。") from exc
    if fmt not in ("PNG", "JPEG"):
        raise InputError("PNG か JPEG の画像だけ受け付けます。")
    if w < 256 or h < 256 or w * h > MAX_PIXELS:
        raise InputError("画像の大きさが範囲外です（256 ピクセル以上、1600 万画素以下）。")
    try:
        im.load()
    except Exception as exc:  # noqa: BLE001
        raise InputError("画像が壊れています。") from exc
    target_mode = 'RGB' if color else 'L'
    keep_raw = (fmt == "JPEG" and im.mode == target_mode and im.size == SAMPLE_SIZE
                and not im.info.get("exif") and not im.info.get("comment") and not im.info.get("icc_profile"))
    im = ImageOps.exif_transpose(im)
    if im.mode in ("RGBA", "LA", "PA") or (im.mode == "P" and "transparency" in im.info):
        rgba = im.convert("RGBA")
        im = Image.alpha_composite(Image.new("RGBA", rgba.size, (255, 255, 255, 255)), rgba)
    pixels = im.convert(target_mode)
    if preserve_aspect:
        # Explanatory pictures may be horizontal or full-body: never cut off their content.
        sample = ImageOps.contain(pixels, (1024, 1024), Image.Resampling.LANCZOS)
        thumb = ImageOps.pad(pixels, THUMB_SIZE, Image.Resampling.LANCZOS, color='white')
        return _jpeg(sample, 85), _jpeg(thumb, 80)
    if keep_raw:
        sample_bytes = raw
    else:
        sample_bytes = _jpeg(ImageOps.fit(pixels, SAMPLE_SIZE, Image.Resampling.LANCZOS, centering=(0.5, 0.4)), 85)
    thumb = ImageOps.fit(pixels, THUMB_SIZE, Image.Resampling.LANCZOS, centering=(0.5, 0.4))
    return sample_bytes, _jpeg(thumb, 80)


class Store:
    def __init__(self, data_dir, catalog_file=CATALOG_FILE, seed_dir=SEED_DIR, compare_dir=COMPARE_DIR):
        self.data_dir = Path(data_dir)
        self.files_dir = self.data_dir / "files"
        self.state_file = self.data_dir / "state.json"
        self.lock = threading.RLock()
        cat = json.loads(Path(catalog_file).read_text(encoding="utf-8"))
        if cat.get("format") != 1:
            raise RuntimeError("unknown catalog.json format")
        self.common = cat["common"]
        self.media = cat.get("media", {})
        self.subjects = cat["subjects"]
        self.character = cat["character"]
        self.scenes = cat["scenes"]
        self.l2_edit = cat["l2_edit"]
        self.step_labels = cat["step_labels"]
        self.l3_scenes = cat["l3_scenes"]
        self.l3_lead = cat["l3_lead"]
        # approved samples: node id -> {sha256, prompt_sha256, style_prompt_sha256, ...}
        # (the pictures themselves live in the volume)
        self.approved = cat["approved_samples"]
        self.avoid = list(cat["avoid"])
        self.avoid_words = cat["avoid_words"]
        self.deny = list(cat["deny"])
        self.base: dict[str, dict] = {}
        self.order: list[str] = []
        self.kids: dict[str | None, list[str]] = {}
        for n in cat["nodes"]:
            src = cat["styles"][n["style"]] if n["level"] == 3 else n
            self.base[n["id"]] = {
                "id": n["id"], "parent": n["parent"], "level": n["level"],
                "title": dict(src["title"]), "summary": dict(src["summary"]), "words": dict(src["words"]),
            }
            if "medium" in src:
                if src["medium"] not in self.media:
                    raise RuntimeError("unknown drawing medium")
                self.base[n["id"]]["medium"] = src["medium"]
            self.order.append(n["id"])
            self.kids.setdefault(n["parent"], []).append(n["id"])
        self._load_compare(Path(compare_dir))
        self.data_dir.mkdir(parents=True, exist_ok=True)
        self.files_dir.mkdir(exist_ok=True)
        with self.lock:
            self.state = self._load()
            created = self._refresh(self.order, now_iso())
            self._import_seeds(Path(seed_dir), created)
            self._import_seeds(Path(seed_dir) / "additions", created)
            pair_dir = Path(seed_dir)/'pairs'
            # Startup holds the lock and serves no requests. Avoid serializing the
            # entire retained catalog twice per pair; commit the final state once.
            self._pair_seed_saving_deferred = True
            self._pair_seed_save_pending = False
            try:
                self._import_pair_seeds(pair_dir)
                for shard in sorted(pair_dir.glob('*')):
                    if shard.is_dir():
                        if shard.is_symlink() or not re.fullmatch('[a-f0-9]{64}', shard.name):
                            raise ValueError('2枚組の配布先が不正です。')
                        self._import_pair_seeds(shard)
            except BaseException as original_error:
                # Retain earlier valid pairs if a later shard is rejected, just
                # as the per-pair commits did. Never publish the failing pair.
                self._pair_seed_saving_deferred = False
                if self._pair_seed_save_pending:
                    try:
                        self._save()
                    except BaseException as flush_error:
                        # Keep the original rejection primary and retain the
                        # independent persistence failure in the traceback.
                        raise original_error from flush_error
                raise
            finally:
                self._pair_seed_saving_deferred = False
            self._save()

    # ------------------------------------------------------------------ persistence
    def _load(self) -> dict:
        if self.state_file.exists():
            state = json.loads(self.state_file.read_text(encoding="utf-8"))
            if state.get("format") != 1:
                raise RuntimeError("unknown state.json format")
            state.setdefault("seeded", [])
            state.setdefault("api", {"mode": "public", "tokens": []})
            return state
        return {"format": 1, "nodes": {}, "seeded": [], "api": {"mode": "public", "tokens": []}}

    def _save(self) -> None:
        if getattr(self, '_pair_seed_saving_deferred', False):
            self._pair_seed_save_pending = True
            return
        _write_atomic(self.state_file, json.dumps(self.state, ensure_ascii=False, indent=1).encode("utf-8"))

    # ------------------------------------------------------------------ reading
    def exists(self, nid) -> bool:
        return nid in self.base

    def effective(self, nid: str) -> dict:
        st = self.state["nodes"][nid]
        n = copy.deepcopy(self.base[nid])
        if st.get('explanatory_style'):
            n['words'] = dict(st['explanatory_style'])
        for field, vals in (st.get("override") or {}).items():
            if st.get('explanatory_style') and field in ('words', 'complete_words'):
                continue  # Preserve old words for legacy descendants, not the new complete style.
            n[field].update(vals)
        n.update(published=st["published"], version=st["version"], updated_at=st["updated_at"],
                 sample=st.get("sample"), regen=st.get("regen"), edited=bool(st.get("override") or st.get('pending_style')))
        return n

    def chain(self, nid: str) -> list[str]:
        out = []
        cur = nid
        while cur is not None:
            out.append(cur)
            cur = self.base[cur]["parent"]
        return out[::-1]

    def visible(self, nid) -> bool:
        if nid not in self.base:
            return False
        return all(self.state["nodes"][c]["published"] for c in self.chain(nid))

    def children(self, nid, visible_only=True) -> list[str]:
        kids = self.kids.get(nid, [])
        return [k for k in kids if self.state["nodes"][k]["published"]] if visible_only else list(kids)

    def shown(self, nid: str, field: str, lang: str) -> str:
        """A shown text field (title or summary; an admin edit wins over the catalogue), without copying."""
        edited = (self.state["nodes"][nid].get("override") or {}).get(field) or {}
        return edited.get(lang) or self.base[nid][field][lang]

    def title(self, nid: str, lang: str) -> str:
        return self.shown(nid, "title", lang)

    def path_titles(self, nid: str, lang: str) -> list[str]:
        """Titles from level 1 down to this branch (its own title last)."""
        return [self.title(c, lang) for c in self.chain(nid)]

    def same_title(self, nid: str, lang: str) -> list[str]:
        """Other visible branches shown under the same title: those under the same level-1 genre first,
        then the rest, each group in catalogue order. Titles are not unique (a level-3 style keeps its name
        under every level-2 branch), so a name alone does not identify a style."""
        name, top = self.title(nid, lang), self.chain(nid)[0]
        same = [k for k in self.order if k != nid and self.title(k, lang) == name and self.visible(k)]
        return sorted(same, key=lambda k: self.chain(k)[0] != top)

    def search(self, query: str, lang: str, limit: int = 200) -> tuple[list[str], int]:
        """Visible branches whose path titles (both languages), summary or id contain every word of the
        query (case-insensitive). Returns (the first `limit` ids in catalogue order, total matches)."""
        words = [w for w in query.casefold().split() if w]
        if not words:
            return [], 0
        hits = []
        for nid in self.order:
            if not self.visible(nid):
                continue
            hay = " ".join(self.path_titles(nid, "ja") + self.path_titles(nid, "en")
                           + [self.shown(nid, "summary", lang), nid]).casefold()
            if all(w in hay for w in words):
                hits.append(nid)
        return hits[:limit], len(hits)

    def descendants(self, nid) -> list[str]:
        out, stack = [], list(reversed(self.kids.get(nid, [])))
        while stack:
            cur = stack.pop()
            out.append(cur)
            stack.extend(reversed(self.kids.get(cur, [])))
        return out

    def prompt_chain(self, nid: str) -> list[str]:
        """The levels whose words make this node's prompt: level 1 alone, else level 2 down to the node."""
        ch = self.chain(nid)
        return ch if len(ch) == 1 else ch[1:]

    def expression(self, nid: str) -> str:
        medium = self.media.get(self.base[nid].get('medium'), {})
        value = medium.get('expression', 'mono')
        if value not in ('mono', 'color'):
            raise RuntimeError('unknown drawing expression')
        return value

    def avoid_for(self, nid: str) -> list[str]:
        expression = self.expression(nid)
        if expression == 'mono':
            return list(self.avoid)
        avoid = [v for v in self.avoid if v != '色']
        return avoid

    def words(self, nid: str) -> dict:
        # Complete per-branch prompts do not leak into legacy descendant recipes.
        out = dict(self.base[nid]['words'])
        out.update((self.state['nodes'][nid].get('override') or {}).get('words', {}))
        return out

    def style_prompt(self, nid: str) -> dict:
        """The API prompt: common words + the words of this node's levels (no subject, person or place)."""
        if self.state['nodes'][nid].get('explanatory_style'):
            return dict(self.effective(nid)['words'])
        words = [self.words(c) for c in self.prompt_chain(nid)]
        common = self.media.get(self.base[nid].get("medium"), {}).get("common", self.common)
        lead = {"ja": "", "en": ""}
        if self.base[nid]["level"] == 3:
            lead = self.l3_lead
        return {
            "ja": " ".join([common["ja"]] + [w["ja"] + "。" for w in words[:-1]]
                           + [lead["ja"] + words[-1]["ja"] + "。"]),
            "en": " ".join([common["en"]] + [w["en"] + "." for w in words[:-1]]
                           + [lead["en"] + words[-1]["en"] + "."]),
            "tags": ", ".join([common["tags"]] + [w["tags"] for w in words]),
        }

    def requested_style(self, nid: str) -> dict:
        """Pending words are for generation only; public readers keep the confirmed pair."""
        return dict(self.state['nodes'][nid].get('pending_style') or self.style_prompt(nid))

    def scene(self, nid: str) -> dict:
        """The sample place and the level-2 scene belong to the level-1 genre."""
        return self.scenes[self.chain(nid)[0]]

    def generation_steps(self, nid: str) -> list[dict]:
        """The prompts for this node's sample: one picture (level 1), or two (level 2 and 3: scene, then redraw)."""
        if self.state['nodes'][nid].get('explanatory_style'):
            sample = self.state['nodes'][nid]['sample']
            return [{lang:self.requested_style(nid)[lang]+sample['prompt_suffix'][lang] for lang in LANGS}]
        ch = self.chain(nid)
        if len(ch) == 2:
            l1, l2 = self.words(ch[0]), self.words(nid)
            scene = self.scene(nid)["l2_scene"]
            edit = self.media.get(self.base[nid].get("medium"), {}).get("edit", self.l2_edit)
            return [
                {lang: " ".join([self.common[lang], l1[lang] + ("。" if lang == "ja" else "."), scene[lang],
                                 self.avoid_words[lang]]) for lang in LANGS},
                {lang: edit[lang].replace("{look}", l2[lang]) for lang in LANGS},
            ]
        if len(ch) == 3:
            l2, l3 = self.words(ch[1]), self.words(nid)
            scene = self.l3_scenes[ch[1]]
            stop = {"ja": "。", "en": "."}
            look = {lang: l2[lang] + stop[lang] + ("" if lang == "ja" else " ") + self.l3_lead[lang] + l3[lang]
                    for lang in LANGS}
            edit = self.media.get(self.base[nid].get("medium"), {}).get("edit", self.l2_edit)
            medium = self.media.get(self.base[nid].get("medium"), {})
            if "medium" in self.base[nid] and not medium.get("retain_parent_look", False):
                look = l3
            return [
                {lang: " ".join([self.common[lang], l2[lang] + stop[lang], scene[lang], self.avoid_words[lang]])
                 for lang in LANGS},
                {lang: edit[lang].replace("{look}", look[lang]) for lang in LANGS},
            ]
        return [self._single_prompt(nid)]

    def generation_prompt(self, nid: str) -> dict:
        """The prompt for this node's sample image; the two steps of a level-2/3 sample are joined with labels."""
        steps = self.generation_steps(nid)
        if len(steps) == 1:
            return steps[0]
        return {lang: "\n\n".join(label + st[lang] for label, st in zip(self.step_labels[lang], steps))
                for lang in LANGS}

    def _single_prompt(self, nid: str) -> dict:
        """One picture: style prompt + subject + person + place + avoid."""
        sp = self.style_prompt(nid)
        sub = self.subjects[SUBJECT]
        place = self.scene(nid)["place"]
        return {
            "ja": " ".join([sp["ja"], "題材: " + sub["ja"], f"人物: {self.character['ja']}",
                            f"場所: {place['ja']}。", self.avoid_words["ja"]]),
            "en": " ".join([sp["en"], "Subject: " + sub["en"], f"The person: {self.character['en']}.",
                            f"Setting: {place['en']}.", self.avoid_words["en"]]),
        }

    def representative(self, nid) -> tuple[str, str] | None:
        """(node id, thumbnail file) of this node's sample, else of the first visible descendant with one."""
        st = self.state["nodes"][nid]
        if st.get("sample"):
            return nid, st["sample"]["thumb"]
        for k in self.children(nid):
            rep = self.representative(k)
            if rep:
                return rep
        return None

    def samples(self, nid: str) -> list[dict]:
        """Representative first, then its application; legacy states remain unchanged."""
        st = self.state["nodes"][nid]
        return ([st["sample"]] + list(st.get("additional_samples", []))) if st.get("sample") else []

    def sample_path(self, nid: str, name: str) -> Path | None:
        for sample in self.samples(nid):
            if name in (sample["file"], sample["thumb"]):
                path = self.files_dir / nid / name
                return path if path.is_file() else None
        return self.compare_path(nid, name)

    # ------------------------------------------------------------------ comparison pictures
    def _load_compare(self, compare_dir: Path) -> None:
        """Read compare/records.json and keep the records whose staged picture is present (size checked;
        prepare_compare.py has checked every SHA-256 before the build). No records file = no comparisons."""
        self.compare_files = compare_dir / "files"
        self.compare_model, self.compare_settings, self.compare = {}, {}, {}
        records_file = compare_dir / "records.json"
        if not records_file.exists():
            return
        records = json.loads(records_file.read_text(encoding="utf-8"))
        if records.get("format") != 1:
            raise RuntimeError("unknown compare records format")
        self.compare_model = dict(records["model"])
        self.compare_settings = dict(records["settings"])
        for nid, rec in records["samples"].items():
            path = self.compare_files / f"{nid}.jpg"
            if nid in self.base and path.is_file() and path.stat().st_size == rec["bytes"]:
                self.compare[nid] = rec

    def comparison(self, nid: str) -> dict | None:
        """The comparison picture of this branch, only while it pairs with the sample shown now: the same
        sample picture it was compared with, and that sample's English prompt is the one it was drawn from.
        A replaced sample (or reworded branch) hides the old comparison instead of showing a wrong pair."""
        rec = self.compare.get(nid)
        sample = self.state["nodes"][nid].get("sample") if nid in self.base else None
        if not rec or not sample:
            return None
        if sample["sha256"] != rec["reference_sha256"]:
            return None
        if hashlib.sha256(sample["prompt"]["en"].encode("utf-8")).hexdigest() != rec["prompt_sha256"]:
            return None
        slug = re.sub(r"[^a-z0-9-]+", "-", self.compare_model["id"].lower()).strip("-")
        return {"file": f"compare-{slug}-{rec['sha256'][:12]}.jpg", "model": self.compare_model,
                "settings": self.compare_settings, "created_at": rec["created_at"], "sha256": rec["sha256"]}

    def compare_path(self, nid: str, name: str) -> Path | None:
        if not COMPARE_NAME.match(name):
            return None
        cmp = self.comparison(nid)
        if not cmp or name != cmp["file"]:
            return None
        path = self.compare_files / f"{nid}.jpg"
        return path if path.is_file() else None

    def fingerprint(self, nid: str) -> str:
        n = self.effective(nid)
        content = {
            "path": [self.effective(c)["title"] for c in self.chain(nid)],
            "summary": n["summary"], "prompt": self.style_prompt(nid), "avoid": self.avoid,
        }
        # 既存monoのfingerprintを保存し、彩色枝のAPI区分と禁止項目だけを追加する。
        expression = self.expression(nid)
        if expression != 'mono':
            content.update(expression=expression, avoid=self.avoid_for(nid))
        return _digest(content)

    def stats(self) -> dict:
        nodes = self.state["nodes"]
        return {
            "total": len(self.order),
            "visible": sum(1 for n in self.order if self.visible(n)),
            "hidden": sum(1 for n in self.order if not nodes[n]["published"]),
            "samples": sum(1 for n in self.order if nodes[n].get("sample")),
            "edited": sum(1 for n in self.order if nodes[n].get("override")),
            "queue": sum(1 for n in self.order if nodes[n].get("regen")),
        }

    def queue(self) -> list[dict]:
        out = []
        for nid in self.order:
            st = self.state["nodes"][nid]
            if st.get("regen"):
                out.append({"id": nid, "path": " > ".join(self.effective(c)["title"]["ja"] for c in self.chain(nid)),
                            "requested_at": st["regen"]["requested_at"], "note": st["regen"].get("note", ""),
                            "has_sample": bool(st.get("sample")), "prompt": self.generation_prompt(nid)})
                if st.get('explanatory_style'):
                    style = self.requested_style(nid)
                    out[-1]['sample_prompts'] = [
                        {'subject':sample['subject'], 'prompt':{lang:style[lang]+sample['prompt_suffix'][lang]
                                                              for lang in LANGS}}
                        for sample in self.samples(nid)]
        return out

    # ------------------------------------------------------------------ changes
    def _refresh(self, ids, ts) -> set:
        """Create missing node states and bump version/updated_at where the API content changed."""
        created = set()
        for nid in ids:
            st = self.state["nodes"].get(nid)
            if st is None:
                st = self.state["nodes"][nid] = {"version": 1, "updated_at": ts, "fingerprint": "",
                                                 "published": True, "override": {}, "sample": None, "regen": None}
                created.add(nid)
                st["fingerprint"] = self.fingerprint(nid)
                continue
            fp = self.fingerprint(nid)
            if fp != st.get("fingerprint"):
                st["fingerprint"] = fp
                st["version"] += 1
                st["updated_at"] = ts
        return created

    def _bump(self, nid: str, ts: str) -> None:
        st = self.state["nodes"][nid]
        st["version"] += 1
        st["updated_at"] = ts

    def _prompts(self, ids: list[str]) -> dict:
        return {k: (self.requested_style(k), self.generation_prompt(k)) for k in ids}

    def _words_changed(self, ids: list[str], before: dict) -> None:
        """After an edit or reset: bump changed API content, and queue the picture of every branch whose
        API prompt or sample prompt changed (a prompt is never updated without its picture)."""
        ts = now_iso()
        self._refresh(ids, ts)
        after = self._prompts(ids)
        for k in ids:
            st = self.state["nodes"][k]
            if st.get("sample") and after[k] != before[k] and not st.get("regen"):
                st["regen"] = {"requested_at": ts, "note": STALE_NOTE}
        self._save()

    def check_text(self, text: str, where: str) -> None:
        for word in self.deny:
            if word in text:
                raise InputError(f"{where}に使えない語（実在の名前など）が入っています: {word}")
        if any(q in text for q in TITLE_BRACKETS):
            raise InputError(f"{where}にかぎかっこ（作品名の疑い）は使えません。")

    def set_published(self, nid: str, published: bool) -> None:
        with self.lock:
            self.state["nodes"][nid]["published"] = bool(published)
            self._save()

    def edit(self, nid: str, values: dict[str, str]) -> None:
        with self.lock:
            base = self.base[nid]
            st = self.state["nodes"][nid]
            ids = [nid] + self.descendants(nid)
            before = self._prompts(ids)
            override = copy.deepcopy(st.get("override") or {})
            pending = self.requested_style(nid)
            for key, raw in values.items():
                if key not in EDITABLE:
                    continue
                field, lang, limit = EDITABLE[key]
                text = " ".join((raw or "").split()) if field != "words" else (raw or "").strip()
                if not text:
                    raise InputError("空の項目があります。")
                if len(text) > limit:
                    raise InputError(f"{key} が長すぎます（{limit} 字まで）。")
                self.check_text(text, "入力")
                if field == 'words' and st.get('explanatory_style'):
                    pending[lang] = text
                    continue
                if text == base[field][lang]:
                    override.get(field, {}).pop(lang, None)
                else:
                    override.setdefault(field, {})[lang] = text
            st["override"] = {k: v for k, v in override.items() if v}
            if st.get('explanatory_style') and pending != self.style_prompt(nid):
                st['pending_style'] = pending
            else:
                st.pop('pending_style', None)
            self._words_changed(ids, before)

    def reset(self, nid: str) -> None:
        with self.lock:
            ids = [nid] + self.descendants(nid)
            before = self._prompts(ids)
            self.state["nodes"][nid]["override"] = {}
            self.state['nodes'][nid].pop('pending_style', None)
            self._words_changed(ids, before)

    def request_regen(self, nid: str, note: str) -> None:
        with self.lock:
            note = " ".join((note or "").split())[:300]
            self.state["nodes"][nid]["regen"] = {"requested_at": now_iso(), "note": note}
            self._save()

    def cancel_regen(self, nid: str) -> None:
        with self.lock:
            self.state["nodes"][nid]["regen"] = None
            self.state['nodes'][nid].pop('pending_style', None)
            self._save()

    def put_sample(self, nid: str, raw: bytes, prompt: dict | None = None, model_version: str | None = None,
                   origin: str = "upload", created_at: str | None = None, bump: bool = True) -> dict:
        """Store a sample. The same picture with the same prompt again changes nothing (safe to re-run)."""
        if self.state['nodes'][nid].get('explanatory_style'):
            raise InputError('この枝は2枚組です。2枚の画像と生成記録を一緒に取り込んでください。')
        prompt = prompt or {}
        if created_at is not None and not ISO_Z.match(created_at):
            raise InputError("作成日時の形が違います（例 2026-09-27T02:05:00Z）。")
        gen = self.generation_prompt(nid)
        clean = {}
        for lang in LANGS:
            text = (prompt.get(lang) or "").strip() or gen[lang]
            if len(text) > PROMPT_LIMIT:
                raise InputError("プロンプトが長すぎます。")
            self.check_text(text, "プロンプト")
            clean[lang] = text
        version = " ".join((model_version or DEFAULT_MODEL_VERSION).split())[:80]
        sample_bytes, thumb_bytes = process_image(raw, color=self.expression(nid) != 'mono')
        with self.lock:
            st = self.state["nodes"][nid]
            old = st.get("sample")
            if (old and not st.get('additional_samples') and old["sha256"] == hashlib.sha256(sample_bytes).hexdigest() and old["prompt"] == clean
                    and old["model"]["version"] == version):
                return old
            k = (old.get("version", 0) + 1) if old else 1
            folder = self.files_dir / nid
            folder.mkdir(exist_ok=True)
            name, thumb = f"{SUBJECT}-v{k}.jpg", f"{SUBJECT}-v{k}-thumb.jpg"
            _write_atomic(folder / name, sample_bytes)
            _write_atomic(folder / thumb, thumb_bytes)
            ts = now_iso()
            st["sample"] = {
                "subject": SUBJECT, "version": k, "file": name, "thumb": thumb,
                "prompt": clean, "model": {"id": MODEL_ID, "version": version},
                "created_at": created_at or ts, "sha256": hashlib.sha256(sample_bytes).hexdigest(),
                "bytes": len(sample_bytes), "origin": origin,
            }
            st.pop('additional_samples', None)
            st["regen"] = None
            if bump:
                self._bump(nid, ts)
            self._save()
            if old and old.get('origin') != 'explanatory-pair':
                for stale in (old["file"], old["thumb"]):
                    try:
                        (folder / stale).unlink()
                    except FileNotFoundError:
                        pass
            return st["sample"]

    def put_sample_pair(self, nid: str, items: list[dict], style_prompt_sha256: str,
                        *, complete_style: dict | None = None) -> list[dict]:
        """Validate both images before one state commit; preserve all superseded image files."""
        if nid not in self.base or len(items) != 2:
            raise InputError("見本は枝ごとに2枚必要です。")
        if [v.get('subject') for v in items] != ['representative', 'application']:
            raise InputError("代表の絵・別の場面の順で指定してください。")
        style = complete_style if complete_style is not None else self.requested_style(nid)
        if not isinstance(style, dict) or set(style) != {'ja', 'en', 'tags'}:
            raise InputError("絵柄の日英プロンプトとタグが必要です。")
        for text in style.values():
            if not isinstance(text, str) or not text.strip() or len(text) > PROMPT_LIMIT:
                raise InputError("絵柄のプロンプトが不正です。")
            self.check_text(text, '絵柄')
        if _digest(style) != style_prompt_sha256:
            raise InputError("絵柄のプロンプトの記録が一致しません。")
        prepared = []
        for item in items:
            prompt = item.get('prompt', {})
            if set(prompt) != set(LANGS) or any(not isinstance(prompt[k], str) or not prompt[k].strip()
                                                or len(prompt[k]) > PROMPT_LIMIT for k in LANGS):
                raise InputError("日英の生成プロンプトが必要です。")
            for text in prompt.values():
                self.check_text(text, "プロンプト")
            model = item.get('model_version')
            created = item.get('created_at')
            if not isinstance(model, str) or not model.strip() or len(model) > 80:
                raise InputError("生成モデルの記録が必要です。")
            if not isinstance(created, str) or not ISO_Z.fullmatch(created):
                raise InputError("作成日時の形が違います。")
            raw, thumb = process_image(item['raw'], color=self.expression(nid) != 'mono', preserve_aspect=True)
            sha = hashlib.sha256(raw).hexdigest()
            with Image.open(io.BytesIO(raw)) as im:
                width, height = im.size
            record = {'subject': item['subject'], 'file': f"{item['subject']}-{sha}.jpg",
                      'thumb': f"{item['subject']}-{sha}-thumb.jpg", 'prompt': dict(prompt),
                      'model': {'id': MODEL_ID, 'version': model}, 'created_at': created,
                      'sha256': sha, 'bytes': len(raw), 'origin': 'explanatory-pair',
                      'width': width, 'height': height, 'style_prompt_sha256': style_prompt_sha256,
                      'prompt_suffix': {lang:prompt[lang][len(style[lang]):] for lang in LANGS}}
            prepared.append((record, raw, thumb))
        records = [p[0] for p in prepared]
        if records[0]['sha256'] == records[1]['sha256']:
            raise InputError("異なる場面の画像を2枚指定してください。")
        with self.lock:
            pending = self.state['nodes'][nid].get('pending_style')
            if pending and _digest(pending) != style_prompt_sha256:
                raise InputError('再生成待ちの最新プロンプトと一致しません。')
            if complete_style is None and _digest(self.requested_style(nid)) != style_prompt_sha256:
                raise InputError("生成時から絵柄のプロンプトが変わっています。")
            old_samples = self.samples(nid)
            for record in records:
                for old in old_samples:
                    if record['sha256'] == old['sha256'] and (
                            record['prompt'] != old['prompt'] or
                            style_prompt_sha256 != old.get('style_prompt_sha256', _digest(self.style_prompt(nid)))):
                        raise InputError('プロンプトを変えた画像は作り直してください。絵柄の変更時は2枚とも必要です。')
            if _digest(self.style_prompt(nid)) != style_prompt_sha256:
                if {r['sha256'] for r in records} & {r['sha256'] for r in old_samples}:
                    raise InputError("絵柄を変えたら2枚とも作り直してください。")
            for record in records:
                if any(not record['prompt'][lang].startswith(style[lang]) for lang in LANGS):
                    raise InputError("生成プロンプトに現在の絵柄が含まれていません。")
            st = self.state['nodes'][nid]
            if self.samples(nid) == records and _digest(self.style_prompt(nid)) == style_prompt_sha256:
                return records
            folder = self.files_dir / nid
            folder.mkdir(exist_ok=True)
            for record, raw, thumb in prepared:
                _write_atomic(folder / record['file'], raw)
                _write_atomic(folder / record['thumb'], thumb)
            before = copy.deepcopy(st)
            try:
                st['sample'], st['additional_samples'] = records[0], records[1:]
                st['explanatory_style'] = dict(style)
                st.get('override', {}).pop('complete_words', None)
                st.pop('pending_style', None)
                st['fingerprint'] = self.fingerprint(nid)
                st['regen'] = None
                self._bump(nid, now_iso())
                self._save()
            except Exception:
                self.state['nodes'][nid] = before
                raise
            return records

    def _import_seeds(self, seed_dir: Path, created: set) -> None:
        manifest = seed_dir / "manifest.json"
        if not manifest.exists():
            return
        for item in json.loads(manifest.read_text(encoding="utf-8")):
            nid = item["id"]
            if nid not in self.base or nid in self.state["seeded"]:
                continue
            if not self.state["nodes"][nid].get("sample"):
                self.put_sample(nid, (seed_dir / item["file"]).read_bytes(), prompt=item["prompt"],
                                model_version=item["model"]["version"], origin="seed",
                                created_at=item.get("created_at"), bump=nid not in created)
            self.state["seeded"].append(nid)

    def _import_pair_seeds(self, folder: Path) -> None:
        from .pair_seed import validate
        manifest = folder/'manifest.json'
        if not manifest.exists():
            return
        if manifest.is_symlink() or manifest.stat().st_size > 2*1024*1024:
            raise ValueError('2枚組の配布記録が大きすぎます。')
        pairs = json.loads(manifest.read_text(encoding='utf-8'))
        paths = list(folder.glob('*.jpg'))
        if len(paths) > 64:
            raise ValueError('一度に取り込む画像が多すぎます。')
        images = {}
        for path in paths:
            if path.is_symlink() or path.stat().st_size > 4*1024*1024:
                raise ValueError('配布画像が不正です。')
            images[path.name] = path.read_bytes()
        validate(pairs, images, set(self.base))
        for pair in pairs:
            nid = pair['id']
            release_sha = _digest(pair)
            if self.state['nodes'][nid].get('pair_seed_sha256') == release_sha:
                continue  # A restart must not undo a later admin edit or imported pair.
            items = [{**{k:v for k,v in item.items() if k not in ('file','sha256','bytes')},
                      'raw':images[item['file']]} for item in pair['samples']]
            history = self.data_dir/'pair-history'
            history.mkdir(exist_ok=True)
            previous = self.state['nodes'][nid]
            _write_atomic(history/(nid+'-'+_digest(previous)+'.json'),
                          json.dumps(previous, ensure_ascii=False, sort_keys=True).encode())
            self.put_sample_pair(nid, items, pair['style_prompt_sha256'], complete_style=pair['complete_style'])
            self.state['nodes'][nid]['pair_seed_sha256'] = release_sha
            self._save()

    # ------------------------------------------------------------------ API access
    def api_mode(self) -> str:
        return self.state["api"]["mode"]

    def tokens(self) -> list[dict]:
        return [{k: t[k] for k in ("id", "label", "created_at")} for t in self.state["api"]["tokens"]]

    def set_api_mode(self, mode: str) -> None:
        if mode not in ("public", "token"):
            raise InputError("公開の方法が正しくありません。")
        with self.lock:
            if mode == "token" and not self.state["api"]["tokens"]:
                raise InputError("限定公開にする前に、トークンを 1 つ作ってください。")
            self.state["api"]["mode"] = mode
            self._save()

    def create_token(self, label: str) -> str:
        label = " ".join((label or "").split())[:60] or "Genko"
        plain = "mst_" + secrets.token_urlsafe(32)
        with self.lock:
            self.state["api"]["tokens"].append({
                "id": secrets.token_hex(4), "label": label, "created_at": now_iso(),
                "sha256": hashlib.sha256(plain.encode()).hexdigest(),
            })
            self._save()
        return plain

    def revoke_token(self, tid: str) -> None:
        with self.lock:
            tokens = self.state["api"]["tokens"]
            rest = [t for t in tokens if t["id"] != tid]
            if len(rest) == len(tokens):
                raise InputError("そのトークンは見つかりません。")
            if not rest and self.state["api"]["mode"] == "token":
                raise InputError("限定公開のあいだは、最後のトークンを消せません。先に公開に戻してください。")
            self.state["api"]["tokens"] = rest
            self._save()

    def check_token(self, plain: str) -> bool:
        digest = hashlib.sha256((plain or "").encode()).hexdigest()
        ok = False
        for t in self.state["api"]["tokens"]:
            ok |= hmac.compare_digest(digest, t["sha256"])
        return ok
